// server/routes/lookup.ts
function mountLookupRoutes(app, { repo, config }) {
  const owner = (res) => {
    const user = userOf(res);
    if (!user.isOwner)
      throw new HttpError(403, "Solo el propietario usa la b\xFAsqueda externa.");
    return user;
  };
  const usage = async () => {
    const serpapi = config.integrations?.serpapi;
    return {
      configured: Boolean(serpapi),
      used: await monthlyCount(repo, [AUDIT.lookup]),
      cap: serpapi?.monthlyCap ?? 0
    };
  };
  app.get("/api/lookup/status", async (_req, res) => {
    owner(res);
    res.json(await usage());
  });
  app.post("/api/lookup", async (req, res) => {
    const user = owner(res);
    const input = z18.object({
      kind: z18.enum(["equipment", "venue", "event"]),
      query: z18.string().trim().min(2).max(200)
    }).strict().parse(req.body);
    const serpapi = config.integrations?.serpapi;
    if (!serpapi) throw new HttpError(503, "B\xFAsqueda externa no conectada.");
    if ((await usage()).used >= serpapi.monthlyCap)
      throw new HttpError(429, "L\xEDmite mensual alcanzado.");
    await rateLimit(repo, `lookup:${user.id}`, 30);
    const results = await serpLookup(
      input.kind,
      input.query,
      serpapi.key,
      config.integrations?.transport
    );
    await repo.audit(
      user.id,
      AUDIT.lookup,
      `${input.kind} \xB7 ${results.length}`
    );
    res.json({ kind: input.kind, results, ...await usage() });
  });
}

