// server/supabase-auth.ts
function supabaseVerifier(url, publishableKey) {
  const base = url.replace(/\/+$/, "");
  const get = async (path, token) => {
    const response = await fetch(`${base}${path}`, {
      headers: {
        apikey: publishableKey,
        Authorization: `Bearer ${token}`,
        Accept: "application/json"
      },
      signal: AbortSignal.timeout(8e3)
    });
    if (!response.ok) throw new Error(`supabase ${response.status}`);
    return response.json();
  };
  return async (accessToken) => {
    const user = await get("/auth/v1/user", accessToken);
    if (!user.id || !user.email) throw new Error("no user");
    const id5 = encodeURIComponent(user.id);
    const profiles = await get(
      `/rest/v1/profiles?id=eq.${id5}&select=role,account_status,full_name`,
      accessToken
    );
    return {
      email: user.email,
      emailVerified: Boolean(user.email_confirmed_at),
      portalRole: profiles[0]?.role ?? "user",
      accountStatus: profiles[0]?.account_status ?? "unknown",
      name: profiles[0]?.full_name || void 0
    };
  };
}

// server/recaptcha.ts
function recaptchaVerifier(projectId, apiKey, siteKey, minScore = 0.5) {
  return async (token, action) => {
    const response = await fetch(
      `https://recaptchaenterprise.googleapis.com/v1/projects/${encodeURIComponent(projectId)}/assessments?key=${encodeURIComponent(apiKey)}`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          event: { token, siteKey, expectedAction: action }
        })
      }
    );
    if (!response.ok) return false;
    const result2 = await response.json();
    return result2.tokenProperties?.valid === true && result2.tokenProperties.action === action && (result2.riskAnalysis?.score ?? 0) >= minScore;
  };
}

